from jsonb_to_recordset($json$[{"id":"che-ek-257","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A plot of $\\ln k$ versus $1/T$ for an Arrhenius reaction is a straight line whose slope equals","options":["$-E_a/R$","$E_a/R$","$-R/E_a$","$A$"],"answer_index":0,"explanation":"$\\ln k = \\ln A - E_a/RT$, so the slope versus $1/T$ is $-E_a/R$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-258","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In $k = A e^{-E_a/RT}$ the pre-exponential factor $A$ is interpreted as","options":["a frequency (or collision) factor, the value $k$ would have if every collision were successful","the activation energy in joules","the gas constant","the equilibrium constant $K_c$"],"answer_index":0,"explanation":"$A$ absorbs the collision frequency and a steric factor. It has the same units as $k$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-259","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A catalyst speeds a reaction primarily by","options":["providing an alternative path with a lower activation energy","raising the temperature of the surroundings","increasing $\\Delta G^\\circ$ of the reaction","changing the stoichiometric coefficients"],"answer_index":0,"explanation":"A lower $E_a$ increases the fraction of successful collisions. $\\Delta H$ and the position of equilibrium stay the same.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-260","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Threshold energy in collision theory is","options":["the minimum relative kinetic energy that a collision must have to be potentially reactive","the average kinetic energy of the whole sample","equal to $RT$ at every temperature","the energy of the products minus $E_a$"],"answer_index":0,"explanation":"Molecules that meet with energy below the threshold simply bounce apart; those above it may react if oriented properly.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-261","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Activation energies of ordinary laboratory reactions are usually quoted in","options":["kJ mol$^{-1}$","volts","siemens","atomic mass units"],"answer_index":0,"explanation":"$E_a$ is a molar energy barrier, typically tens to a few hundred kJ mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-262","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Between two reactions at the same $T$, the one with the larger $E_a$ is","options":["more sensitive to a change of temperature","always faster at every temperature","unaffected by heating","required to have a negative $A$ factor"],"answer_index":0,"explanation":"d ln $k$ / d$T$ = $E_a/RT^2$, so a higher barrier means a steeper rise of $k$ with $T$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-263","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The two-temperature form of the Arrhenius equation is","options":["$\\log(k_2/k_1) = (E_a/2.303R)(1/T_1 - 1/T_2)$","$\\log(k_2/k_1) = (E_a/R)(T_2 - T_1)$","$k_2/k_1 = E_a (T_2 - T_1)$","$\\log(k_2/k_1) = 2.303R / E_a$"],"answer_index":0,"explanation":"Subtracting $\\ln k = \\ln A - E_a/RT$ at two temperatures eliminates $A$ and gives that working equation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-264","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"In the formal high-temperature limit of the Arrhenius expression, $k$ approaches","options":["the pre-exponential factor $A$","zero","the Faraday constant","$E_a$ itself"],"answer_index":0,"explanation":"As $T \\to \\infty$, $e^{-E_a/RT} \\to 1$, so $k \\to A$. Real molecules decompose before that limit is reached.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-265","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A reaction has $k = 2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$ at 300 K and $8.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$ at 320 K. $E_a$ is nearest","options":["55 kJ mol$^{-1}$","8.3 kJ mol$^{-1}$","220 kJ mol$^{-1}$","2.0 kJ mol$^{-1}$"],"answer_index":0,"explanation":"$\\log 4 = 0.602 = (E_a/19.15)(1/300 - 1/320)$; $1/300 - 1/320 = 2.08 \\times 10^{-4}$, so $E_a \\approx 55\\ \\mathrm{kJ\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-266","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $E_a = 57.4\\ \\mathrm{kJ\\ mol^{-1}}$, the factor by which $k$ grows when $T$ goes from 300 K to 310 K is nearest","options":["2","10","0.5","100"],"answer_index":0,"explanation":"$\\log(k_2/k_1) = (57400/19.15)(10/93000) \\approx 0.32$, so $k_2/k_1 \\approx 2$. This is the familiar “about double per 10 K” case.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-267","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Given $k = 1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$ at 300 K and $E_a = 38.3\\ \\mathrm{kJ\\ mol^{-1}}$, $k$ at 310 K is nearest","options":["$1.6 \\times 10^{-4}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$3.8 \\times 10^{-2}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"$\\log(k_2/k_1) = (38300/19.15)(10/93000) \\approx 0.215$, so $k_2 \\approx 1.6 \\times 10^{-4}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-268","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"On an Arrhenius plot of $\\ln k$ versus $1/T$ the intercept (extrapolated to $1/T = 0$) equals","options":["$\\ln A$","$-E_a$","$A$","$E_a/R$"],"answer_index":0,"explanation":"$\\ln k = \\ln A - (E_a/R)(1/T)$. The intercept of that straight line is $\\ln A$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
